using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "ActionGainVariableHexDieActionCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/ActionGainVariableHexDieActionCustomDescription", order = 0)]
public class ActionGainVariableHexDieActionCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		ActionGainVariableHexDieAction obj = battleAction as ActionGainVariableHexDieAction;
		string actionDescription = obj.BattleAction.GetActionDescription(0, 0);
		string actionDescription2 = obj.HexAction.GetActionDescription(GetAmountWithoutEquation(amountModified), 0);
		return actionDescription + "\n" + actionDescription2;
	}
}
